CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT DEFAULT 'Guest User',phone TEXT UNIQUE,email TEXT,addr TEXT,diet TEXT DEFAULT 'any',av TEXT DEFAULT '🌾',theme TEXT DEFAULT 'auto',role TEXT DEFAULT 'get',points INTEGER DEFAULT 120,earn INTEGER DEFAULT 0,online INTEGER DEFAULT 0,created_at INTEGER);
CREATE TABLE IF NOT EXISTS otps(phone TEXT PRIMARY KEY,code TEXT,exp INTEGER);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,name TEXT,type TEXT CHECK(type IN('donor','hub')),x REAL,y REAL,need INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS partners(id INTEGER PRIMARY KEY,name TEXT,x REAL,y REAL,rating REAL DEFAULT 4.9,online INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS listings(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,emoji TEXT,donor_id TEXT REFERENCES nodes(id),qty INTEGER,mode TEXT DEFAULT 'free',price INTEGER DEFAULT 0,category TEXT,veg INTEGER DEFAULT 1,auto INTEGER DEFAULT 0,expires_at INTEGER);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,donor_id TEXT,total INTEGER,status TEXT DEFAULT 'confirmed',progress REAL DEFAULT 0,partner_id INTEGER,created_at INTEGER);
CREATE TABLE IF NOT EXISTS order_items(order_id INTEGER,listing_id INTEGER,name TEXT,qty INTEGER,price INTEGER);
CREATE TABLE IF NOT EXISTS rescues(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,emoji TEXT,qty INTEGER,from_id TEXT,to_id TEXT,partner_id INTEGER,tries INTEGER DEFAULT 1,event TEXT,progress REAL DEFAULT 0,fail_at REAL,status TEXT DEFAULT 'active',expires_at INTEGER,created_at INTEGER);
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,listing_id INTEGER,pay INTEGER,created_at INTEGER);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,icon TEXT,text TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS stats(k TEXT PRIMARY KEY,v INTEGER);